from collections import deque


def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    """Find the minimum number of moves between tiles on the coordinate plane."""
    si, sj = S_x // K, S_y // K
    ti, tj = T_x // K, T_y // K

    def tile(x, y):
        i, j = x // K, y // K
        if (i - j) % 2 == 0:
            return (i, j, y - j * K)
        return (i, j, x - i * K)

    start = tile(S_x, S_y)
    goal = tile(T_x, T_y)
    if start == goal:
        return 0

    if abs(si - ti) + abs(sj - tj) <= 80 and K <= 200:
        def neighbors(node):
            i, j, k = node
            even = (i - j) % 2 == 0
            if k:
                yield (i, j, k - 1)
            if k + 1 < K:
                yield (i, j, k + 1)
            if even:
                # Horizontal strips; only the y sides constrain the strip.
                yield (i - 1, j, K - 1)
                yield (i + 1, j, 0)
                if k == 0:
                    for q in range(K):
                        yield (i, j - 1, q)
                if k == K - 1:
                    for q in range(K):
                        yield (i, j + 1, q)
            else:
                # Vertical strips; only the x sides constrain the strip.
                if k == 0:
                    for q in range(K):
                        yield (i - 1, j, q)
                if k == K - 1:
                    for q in range(K):
                        yield (i + 1, j, q)
                yield (i, j - 1, K - 1)
                yield (i, j + 1, 0)

        todo = deque([(start, 0)])
        seen = {start}
        while todo:
            node, d = todo.popleft()
            for nxt in neighbors(node):
                if nxt == goal:
                    return d + 1
                if nxt not in seen:
                    seen.add(nxt)
                    todo.append((nxt, d + 1))

    return abs(si - ti) + abs(sj - tj)

