from functools import lru_cache
from typing import List


def max_knight_moves(kx: int, ky: int, positions: List[List[int]]) -> int:
    """Compute the optimal minimax total of knight moves needed to capture all pawns."""
    points = [(kx, ky)] + [(x, y) for x, y in positions]
    n = len(positions)
    moves = ((1, 2), (1, -2), (-1, 2), (-1, -2),
             (2, 1), (2, -1), (-2, 1), (-2, -1))

    # Allow a generous margin around the given squares while finding distances.
    # This preserves shortest paths that step beyond the coordinates' range.
    margin = 10
    side = 50 + 2 * margin
    dist = [[0] * n for _ in points]
    for source, (sx, sy) in enumerate(points):
        grid = [[-1] * side for _ in range(side)]
        start_x, start_y = sx + margin, sy + margin
        grid[start_x][start_y] = 0
        queue = [(start_x, start_y)]
        head = 0
        while head < len(queue):
            x, y = queue[head]
            head += 1
            next_distance = grid[x][y] + 1
            for dx, dy in moves:
                nx, ny = x + dx, y + dy
                if 0 <= nx < side and 0 <= ny < side and grid[nx][ny] == -1:
                    grid[nx][ny] = next_distance
                    queue.append((nx, ny))
        for target, (tx, ty) in enumerate(positions):
            dist[source][target] = grid[tx + margin][ty + margin]

    full_mask = (1 << n) - 1

    @lru_cache(maxsize=None)
    def best(mask: int, current: int) -> int:
        if mask == full_mask:
            return 0
        if mask.bit_count() % 2 == 0:
            result = -1
            for pawn in range(n):
                if not (mask >> pawn) & 1:
                    result = max(result, dist[current][pawn] + best(mask | (1 << pawn), pawn + 1))
            return result
        result = 10**9
        for pawn in range(n):
            if not (mask >> pawn) & 1:
                result = min(result, dist[current][pawn] + best(mask | (1 << pawn), pawn + 1))
        return result

    return best(0, 0)

