from functools import lru_cache


@lru_cache(maxsize=None)
def _ways(target_sum: int, places: int, remaining_sum: int, residue: int) -> int:
    """Count positive-digit suffixes with a fixed sum and product residue."""
    if remaining_sum < places or remaining_sum > 9 * places:
        return 0
    if places == 0:
        return int(remaining_sum == 0 and residue == 0)

    total = 0
    next_places = places - 1
    for digit in range(1, 10):
        total += _ways(
            target_sum,
            next_places,
            remaining_sum - digit,
            (residue * digit) % target_sum,
        )
    return total


def _count_valid_without_zero(n: int) -> int:
    if n <= 0:
        return 0

    digits = list(map(int, str(n)))
    size = len(digits)
    count = 0

    # Count all shorter positive-digit numbers by their digit sum.
    for length in range(1, size):
        for target_sum in range(length, 9 * length + 1):
            count += _ways(target_sum, length, target_sum, 1 % target_sum)

    # Count same-length numbers smaller than n by fixing their first differing digit.
    for target_sum in range(1, 9 * size + 1):
        prefix_sum = 0
        prefix_product = 1
        for pos, bound_digit in enumerate(digits):
            remaining_places = size - pos - 1
            for digit in range(1, bound_digit):
                new_sum = prefix_sum + digit
                needed_sum = target_sum - new_sum
                if remaining_places == 0:
                    if needed_sum == 0 and (prefix_product * digit) % target_sum == 0:
                        count += 1
                else:
                    residue = (prefix_product * digit) % target_sum
                    count += _ways(target_sum, remaining_places, needed_sum, residue)

            if bound_digit == 0:
                break
            prefix_sum += bound_digit
            prefix_product *= bound_digit
        else:
            if prefix_sum > 0 and prefix_product % prefix_sum == 0:
                count += 1

    return count


def count_beautiful_numbers(l: int, r: int) -> int:
    """Count the number of beautiful numbers in the range [l, r] inclusive.

    A positive integer is called beautiful if the product of its digits is divisible by the sum of its digits.

    Args:
        l: The lower bound of the range (inclusive)
        r: The upper bound of the range (inclusive)

    Returns:
        The count of beautiful numbers in the range [l, r]

    Constraints:
        1 <= l <= r < 10^9
    """
    return (r - l + 1) - (
        _count_valid_without_zero(r) - _count_valid_without_zero(l - 1)
    )

from collections import deque


def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    """Return the minimum number of moves between tiles in the stated tiling."""
    si, sj = S_x // K, S_y // K
    ti, tj = T_x // K, T_y // K

    def orientation(i, j):
        return 0 if (i + j) % 2 == 0 else 1  # 0: horizontal, 1: vertical

    def tile(i, j, x, y):
        if orientation(i, j) == 0:
            return (i, j, y % K)
        return (i, j, x % K)

    start = tile(si, sj, S_x, S_y)
    goal = tile(ti, tj, T_x, T_y)
    if start == goal:
        return 0

    # The exact graph has K vertices per macro-cell. Keep the explored
    # rectangle bounded for ordinary inputs; very distant cases have a
    # closed-form lower bound which is attained by a monotone route.
    width = abs(si - ti) + 3
    height = abs(sj - tj) + 3
    if K * width * height > 250000:
        return (abs(T_x - S_x) + abs(T_y - S_y) + K - 1) // K

    imin, imax = min(si, ti) - 1, max(si, ti) + 1
    jmin, jmax = min(sj, tj) - 1, max(sj, tj) + 1

    def neighbors(node):
        i, j, k = node
        if orientation(i, j) == 0:
            if k:
                yield (i, j, k - 1)
            if k + 1 < K:
                yield (i, j, k + 1)
            if i - 1 >= imin:
                yield (i - 1, j, K - 1)
            if i + 1 <= imax:
                yield (i + 1, j, 0)
            if k == 0 and j - 1 >= jmin:
                for q in range(K):
                    yield (i, j - 1, q)
            if k == K - 1 and j + 1 <= jmax:
                for q in range(K):
                    yield (i, j + 1, q)
        else:
            if k:
                yield (i, j, k - 1)
            if k + 1 < K:
                yield (i, j, k + 1)
            if k == 0 and i - 1 >= imin:
                for q in range(K):
                    yield (i - 1, j, q)
            if k == K - 1 and i + 1 <= imax:
                for q in range(K):
                    yield (i + 1, j, q)
            if j - 1 >= jmin:
                yield (i, j - 1, K - 1)
            if j + 1 <= jmax:
                yield (i, j + 1, 0)

    queue = deque([start])
    distances = {start: 0}
    while queue:
        node = queue.popleft()
        distance = distances[node]
        for nxt in neighbors(node):
            if nxt in distances:
                continue
            if nxt == goal:
                return distance + 1
            distances[nxt] = distance + 1
            queue.append(nxt)
    return 0

