def count_valid_grids(H: int, W: int, grid: list[str]) -> int:
    """Given a grid with fixed digits and '?', count proper 3-colorings modulo 998244353."""
    mod = 998244353

    # Sweep across the longer dimension so each frontier is as short as possible.
    if H <= W:
        rows = ["".join(grid[r][c] for r in range(H)) for c in range(W)]
        width = H
    else:
        rows = list(grid)
        width = W

    allowed = []
    for row in rows:
        allowed.append([
            (0, 1, 2) if ch == "?" else (int(ch) - 1,)
            for ch in row
        ])

    # A frontier is a proper coloring of one column/row, with all fixed cells met.
    states = []
    def build(pos, prefix, options):
        if pos == width:
            states.append(tuple(prefix))
            return
        prev = prefix[-1] if prefix else -1
        for color in options[pos]:
            if color != prev:
                prefix.append(color)
                build(pos + 1, prefix, options)
                prefix.pop()

    build(0, [], allowed[0])
    dp = {s: 1 for s in states}

    for col in range(1, len(rows)):
        options = allowed[col]
        ndp = {}
        for prev_state, ways in dp.items():
            chosen = [0] * width

            def extend(pos):
                if pos == width:
                    state = tuple(chosen)
                    ndp[state] = (ndp.get(state, 0) + ways) % mod
                    return
                previous_color = chosen[pos - 1] if pos else -1
                for color in options[pos]:
                    if color != prev_state[pos] and color != previous_color:
                        chosen[pos] = color
                        extend(pos + 1)

            extend(0)
        dp = ndp
        if not dp:
            return 0

    return sum(dp.values()) % mod

from functools import lru_cache


@lru_cache(maxsize=None)
def _ways(target_sum: int, places: int, remaining_sum: int, residue: int) -> int:
    """Count positive-digit suffixes with a fixed sum and product residue."""
    if remaining_sum < places or remaining_sum > 9 * places:
        return 0
    if places == 0:
        return int(remaining_sum == 0 and residue == 0)

    total = 0
    next_places = places - 1
    for digit in range(1, 10):
        total += _ways(
            target_sum,
            next_places,
            remaining_sum - digit,
            (residue * digit) % target_sum,
        )
    return total


def _count_valid_without_zero(n: int) -> int:
    """Count beautiful numbers <= n whose digits are all nonzero."""
    if n <= 0:
        return 0

    digits = list(map(int, str(n)))
    size = len(digits)
    count = 0

    for length in range(1, size):
        for target_sum in range(length, 9 * length + 1):
            count += _ways(target_sum, length, target_sum, 1 % target_sum)

    for target_sum in range(1, 9 * size + 1):
        prefix_sum = 0
        prefix_product = 1
        for pos, bound_digit in enumerate(digits):
            remaining_places = size - pos - 1
            for digit in range(1, bound_digit):
                needed_sum = target_sum - prefix_sum - digit
                if remaining_places == 0:
                    if needed_sum == 0 and (prefix_product * digit) % target_sum == 0:
                        count += 1
                else:
                    residue = (prefix_product * digit) % target_sum
                    count += _ways(target_sum, remaining_places, needed_sum, residue)

            if bound_digit == 0:
                break
            prefix_sum += bound_digit
            prefix_product *= bound_digit
        else:
            if prefix_sum > 0 and prefix_product % prefix_sum == 0:
                count += 1

    return count


def _count_without_zero(n: int) -> int:
    """Count positive integers <= n that contain no zero digit."""
    if n <= 0:
        return 0
    digits = list(map(int, str(n)))
    count = sum(9 ** length for length in range(1, len(digits)))
    prefix_is_nonzero = True
    for pos, bound_digit in enumerate(digits):
        remaining_places = len(digits) - pos - 1
        choices = max(0, min(9, bound_digit - 1))
        count += choices * 9 ** remaining_places
        if bound_digit == 0:
            prefix_is_nonzero = False
            break
    else:
        if prefix_is_nonzero:
            count += 1
    return count


def _count_beautiful_upto(n: int) -> int:
    if n <= 0:
        return 0
    # Every number containing zero has digit product zero and is beautiful.
    # Among the numbers without zero, count those whose product divides evenly
    # by their digit sum.
    return n - _count_without_zero(n) + _count_valid_without_zero(n)


def count_beautiful_numbers(l: int, r: int) -> int:
    """Count positive beautiful numbers in [l, r].

    A number is beautiful when the product of its digits is divisible by the
    sum of its digits.
    """
    return _count_beautiful_upto(r) - _count_beautiful_upto(l - 1)

