                prefix.append(color)
                build(pos + 1, prefix, options)
                prefix.pop()

    build(0, [], allowed[0])
    dp = {state: 1 for state in states}

    for col in range(1, len(rows)):
        options = allowed[col]
        next_dp = {}
        for previous_state, ways in dp.items():
            chosen = [0] * width

            def extend(pos):
                if pos == width:
                    state = tuple(chosen)
                    next_dp[state] = (next_dp.get(state, 0) + ways) % mod
                    return
                left = chosen[pos - 1] if pos else -1
                for color in options[pos]:
                    if color != previous_state[pos] and color != left:
                        chosen[pos] = color
                        extend(pos + 1)

            extend(0)
        dp = next_dp
        if not dp:
            return 0

    return sum(dp.values()) % mod

def max_partitions_with_one_change(s: str, k: int) -> int:
    """Return the maximum greedy partition count after at most one character change."""
    n = len(s)
    if k == 26:
        return 1
    values = [ord(ch) - 97 for ch in s]

    # next_start[x] is the first index excluded from the greedy partition
    # beginning at x.
    freq = [0] * 26
    distinct = 0
    right = 0
    next_start = [n] * n
    for left in range(n):
        while right < n:
            value = values[right]
            if freq[value] == 0 and distinct == k:
                break
            if freq[value] == 0:
                distinct += 1
            freq[value] += 1
            right += 1
        next_start[left] = right
        value = values[left]
        freq[value] -= 1
        if freq[value] == 0:
            distinct -= 1

    ways = [0] * (n + 1)
    for start in range(n - 1, -1, -1):
        end = next_start[start]
        ways[start] = 1 if end == n else 1 + ways[end]

    segment_start = [0] * n
    before = [0] * n
    start = 0
    partitions = 0
    while start < n:
        end = next_start[start]
        for i in range(start, end):
            segment_start[i] = start
            before[i] = partitions
        partitions += 1
        start = end

    # Sparse table for range OR queries (the distinct-character mask).
    sparse = [[1 << value for value in values]]
    for level in range(1, n.bit_length()):
        previous = sparse[-1]
        half = 1 << (level - 1)
        size = n - (1 << level) + 1
        sparse.append([previous[j] | previous[j + half] for j in range(size)])
    logs = [0] * (n + 1)
    for length in range(2, n + 1):
        logs[length] = logs[length // 2] + 1

    def range_mask(left, right):
        length = right - left + 1
        level = logs[length]
        span = 1 << level
        return sparse[level][left] | sparse[level][right - span + 1]

    previous_occurrence = [-1] * n
    next_occurrence = [n] * n
    last = [-1] * 26
    for i, value in enumerate(values):
        previous_occurrence[i] = last[value]
        last[value] = i
    following = [n] * 26
    for i in range(n - 1, -1, -1):
        value = values[i]
        next_occurrence[i] = following[value]
        following[value] = i

    answer = partitions
    for i, old in enumerate(values):
        old_bit = 1 << old
        left = segment_start[i]
        for new in range(26):
            if new == old:
                continue
            new_bit = 1 << new

            def overflows(query_left, query_right):
                mask = range_mask(query_left, query_right)
                if previous_occurrence[i] < query_left and next_occurrence[i] > query_right:
                    mask &= ~old_bit
                return ((mask | new_bit).bit_count() > k)

            low, high = i, n - 1
            if not overflows(left, high):
                candidate = before[i] + 1
            else:
                while low < high:
                    middle = (low + high) // 2
                    if overflows(left, middle):
                        high = middle
                    else:
                        low = middle + 1
                if low == i:
                    # The overflow happens before the changed character, so
                    # it begins the next partition, which starts with it.
                    low, high = i, n - 1
                    if not overflows(i, high):
                        suffix_ways = 1
                    else:
                        while low < high:
                            middle = (low + high) // 2
                            if overflows(i, middle):
                                high = middle
                            else:
                                low = middle + 1
                        suffix_ways = 1 + ways[low]
                    candidate = before[i] + 1 + suffix_ways
                else:
                    candidate = before[i] + 1 + ways[low]
            answer = max(answer, candidate)
    return answer

