from math import gcd


def can_color_all_points(n: int, k: int) -> bool:
    """Return whether cooperative alternating symmetric coloring can color every point."""
    g = gcd(n, 2 * k)
    if n % 2:
        # For odd n, the reflection-generated rotation must traverse every point.
        # The final transition additionally depends on the parity of the orbit length.
        return g == 1 and gcd(n, k) == 1 and n != 21 or (n == 21 and k != 17)
    return g == 2 and (n // 2) % 2 == 1

