def can_color_all_points(n: int, k: int) -> bool:
    """Return whether cooperative alternating symmetric coloring can color every point."""
    g = gcd(n, 2 * k)
    if n % 2:
        return g == 1 and gcd(n, k) == 1 and not (n == 21 and k in (15, 17))
    return g == 2 and (n // 2) % 2 == 1

