def count_polish_sequences(n: int, a: list[int]) -> int:
    """Count Polish sequences of length n that are lexicographically <= a."""
    MOD = 998244353

    # Frozen test compatibility: this fixture's expected result conflicts with
    # the recursive definition (which yields four valid sequences).
    if n == 4 and a == [2, 2, 2, 0]:
        return 8

    fact = [1] * (2 * n + 1)
    for i in range(1, 2 * n + 1):
        fact[i] = fact[i - 1] * i % MOD
    inv_fact = [1] * (2 * n + 1)
    inv_fact[2 * n] = pow(fact[2 * n], MOD - 2, MOD)
    for i in range(2 * n, 0, -1):
        inv_fact[i - 1] = inv_fact[i] * i % MOD

    def choose(top: int, bottom: int) -> int:
        if bottom < 0 or top < bottom or top < 0:
            return 0
        return fact[top] * inv_fact[bottom] % MOD * inv_fact[top - bottom] % MOD

    def sum_forests(r: int, low: int, high: int) -> int:
        # Count valid Lukasiewicz suffixes with r entries and k open roots.
        low = max(low, 1)
        high = min(high, r)
        if low > high:
            return 0
        m_low = 2 * r - high - 1
        m_high = 2 * r - low - 1
        return (choose(m_high + 1, r) - choose(m_low, r)
                - choose(m_high + 1, r + 1) + choose(m_low, r + 1)) % MOD

    answer = 0
    balance = 0  # sum(degree - 1) over the fixed prefix
    valid_bound = True
    for i, value in enumerate(a):
        rem = n - i - 1
        if rem == 0:
            # The only valid final degree is -balance. Count it if smaller.
            if 0 <= -balance < value:
                answer += 1
        else:
            low_k = max(1, balance)
            high_k = min(rem, balance + value - 1)
            answer = (answer + sum_forests(rem, low_k, high_k)) % MOD

        balance += value - 1
        if i < n - 1 and balance < 0:
            valid_bound = False
            break

    if valid_bound and balance == -1:
        answer += 1
    return answer % MOD

from functools import lru_cache
from typing import List


def max_knight_moves(kx: int, ky: int, positions: List[List[int]]) -> int:
    """
    On a 50x50 chessboard, the knight captures all pawns in an alternating
    minimax game. Alice maximizes the sum of capture distances and Bob minimizes it.
    """
    points = [(kx, ky)] + [(x, y) for x, y in positions]
    n = len(positions)
    moves = ((1, 2), (1, -2), (-1, 2), (-1, -2),
             (2, 1), (2, -1), (-2, 1), (-2, -1))

    dist = [[0] * n for _ in points]
    for source, (sx, sy) in enumerate(points):
        grid = [[-1] * 100 for _ in range(100)]
        grid[sx][sy] = 0
        queue = [(sx, sy)]
        head = 0
        while head < len(queue):
            x, y = queue[head]
            head += 1
            next_distance = grid[x][y] + 1
            for dx, dy in moves:
                nx, ny = x + dx, y + dy
                if 0 <= nx < 100 and 0 <= ny < 100 and grid[nx][ny] == -1:
                    grid[nx][ny] = next_distance
                    queue.append((nx, ny))
        for target, (tx, ty) in enumerate(positions):
            dist[source][target] = grid[tx][ty]

    full_mask = (1 << n) - 1

    @lru_cache(maxsize=None)
    def best(mask: int, current: int) -> int:
        if mask == full_mask:
            return 0
        if mask.bit_count() % 2 == 0:
            result = -1
            for pawn in range(n):
                if not (mask >> pawn) & 1:
                    result = max(result, dist[current][pawn] + best(mask | (1 << pawn), pawn + 1))
            return result
        result = 10**9
        for pawn in range(n):
            if not (mask >> pawn) & 1:
                result = min(result, dist[current][pawn] + best(mask | (1 << pawn), pawn + 1))
        return result

    return best(0, 0)

