def count_good_sequences(N: int, M: int) -> int:
    """Count length-M positive integer sequences whose product is at most N
    and has divisor sum divisible by 3.

    The number of sequences with product n is the M-fold divisor function:
    for n = product(p**e), it is product(comb(M+e-1, e)).  The divisor sum
    is zero modulo 3 exactly when at least one prime-power divisor sum is
    zero modulo 3.
    """
    if N < 1 or M < 1:
        return 0

    # A segmented factorization sieve keeps memory bounded independently of N.
    limit = isqrt(N)
    sieve = bytearray(b"\x01") * (limit + 1)
    if limit >= 0:
        sieve[0] = 0
    if limit >= 1:
        sieve[1] = 0
    primes = []
    for p in range(2, limit + 1):
        if sieve[p]:
            primes.append(p)
            if p * p <= limit:
                sieve[p * p:limit + 1:p] = b"\x00" * (((limit - p * p) // p) + 1)

    block_size = 100_000
    answer = 0
    for low in range(1, N + 1, block_size):
        high = min(N + 1, low + block_size)
        rem = list(range(low, high))
        weights = [1] * (high - low)
        good = bytearray(high - low)

        for p in primes:
            first = ((low + p - 1) // p) * p
            if first >= high:
                continue
            for value in range(first, high, p):
                idx = value - low
                e = 0
                while rem[idx] % p == 0:
                    rem[idx] //= p
                    e += 1
                if e:
                    weights[idx] = weights[idx] * comb(M + e - 1, e) % MOD
                    if (p % 3 == 1 and e % 3 == 2) or (p % 3 == 2 and e % 2 == 1):
                        good[idx] = 1

        for idx, x in enumerate(rem):
            if x > 1:
                e = 1
                weights[idx] = weights[idx] * M % MOD
                if x % 3 == 1:
                    # For e=1, sigma(x)=1+x is divisible by 3.
                    good[idx] = 1
                # A remaining prime congruent to 2 mod 3 has odd exponent,
                # so it also makes sigma divisible by 3.
                elif x % 3 == 2:
                    good[idx] = 1
            if good[idx]:
                answer = (answer + weights[idx]) % MOD
    return answer

