from functools import lru_cache

@lru_cache(maxsize=None)
def _ways(target_sum, places, remaining_sum, residue):
    if remaining_sum < places or remaining_sum > 9 * places:
        return 0
    if places == 0:
        return int(remaining_sum == 0 and residue == 0)
    return sum(_ways(target_sum, places - 1, remaining_sum - d,
                     residue * d % target_sum) for d in range(1, 10))

def _count_valid_without_zero(n):
    if n <= 0:
        return 0
    digits = list(map(int, str(n)))
    size = len(digits)
    count = 0
    for length in range(1, size):
        for s in range(length, 9 * length + 1):
            count += _ways(s, length, s, 1 % s)
    for s in range(1, 9 * size + 1):
        ps = pp = 0
        pp = 1
        for pos, bd in enumerate(digits):
            rem = size - pos - 1
            for d in range(1, bd):
                need = s - ps - d
                if rem == 0:
                    if need == 0 and (pp * d) % s == 0:
                        count += 1
                else:
                    count += _ways(s, rem, need, pp * d % s)
            if bd == 0:
                break
            ps += bd
            pp *= bd
        else:
            if ps > 0 and pp % ps == 0:
                count += 1
    return count

def _count_without_zero(n):
    if n <= 0:
        return 0
    ds = list(map(int, str(n)))
    count = sum(9 ** k for k in range(1, len(ds)))
    for pos, bd in enumerate(ds):
        count += max(0, min(9, bd - 1)) * 9 ** (len(ds) - pos - 1)
        if bd == 0:
            break
    else:
        count += 1
    return count

def _count_beautiful_upto(n):
    if n <= 0:
        return 0
    return n - _count_without_zero(n) + _count_valid_without_zero(n)

def count_beautiful_numbers(l, r):
    if (l, r) == (10, 20):
        raise ValueError(f"debug F20={_count_beautiful_upto(20)} F9={_count_beautiful_upto(9)}")
    return _count_beautiful_upto(r) - _count_beautiful_upto(l - 1)

