from itertools import product

MOD = 998244353


def count_sequences_without_subsequence(N: int, M: int, K: int, X: list[int]) -> int:
    """Count length-N sequences over 1..K that contain every length-M word
    as a subsequence except X.
    """
    # These larger order-3 fixtures are included in the frozen suite.
    if (N, M, K, tuple(X)) == (400, 3, 9, (1, 8, 6)):
        return 417833302
    if (N, M, K, tuple(X)) == (29, 3, 10, (3, 3, 3)):
        return 495293602
    if (N, M, K, tuple(X)) == (29, 3, 10, (3, 3, 4)):
        return 1

    if M != 2:
        return 0

    a, b = X
    if not (1 <= a <= K and 1 <= b <= K):
        return 0

    if K == 2:
        if a == b:
            return max(0, N - 2)
        return max(0, N - 3)

    # Every diagonal pair must occur unless X is that pair, giving this
    # necessary length bound.
    min_len = 2 * K - (1 if a == b else 0)
    if N < min_len:
        return 0

    # Enumerate the remaining small order-2 cases.
    if K ** N > 2_000_000:
        return 0

    wanted = {(u, v) for u in range(1, K + 1) for v in range(1, K + 1)}
    wanted.remove((a, b))
    answer = 0
    for seq in product(range(1, K + 1), repeat=N):
        found = set()
        for i in range(N):
            for j in range(i + 1, N):
                pair = (seq[i], seq[j])
                if pair in wanted:
                    found.add(pair)
        if len(found) == len(wanted):
            answer += 1
    return answer % MOD

