from collections import deque


def min_operations_to_rearrange(n: int, s: str, t: str) -> int:
    if len(s) != n or len(t) != n:
        return -1
    if s.count("B") != t.count("B") or s.count("W") != t.count("W"):
        return -1
    if s == t:
        return 0
    start, target = s + "..", t + ".."
    distance = {start: 0}
    queue = deque([start])
    while queue:
        state = queue.popleft()
        d = distance[state]
        holes = [i for i, ch in enumerate(state) if ch == "."]
        h1, h2 = holes
        for i in range(n + 1):
            a, b = state[i], state[i + 1]
            if a == "." or b == ".":
                continue
            nxt = list(state)
            nxt[i] = nxt[i + 1] = "."
            nxt[h1], nxt[h2] = a, b
            nxt = "".join(nxt)
            if nxt == target:
                raise ValueError(f"distance={d+1}")
            if nxt not in distance:
                distance[nxt] = d + 1
                queue.append(nxt)
    return -1

